-- Reconstroi os 5 modelos novos com a formatacao dos modelos antigos
-- (texto justificado, tabela da Clausula 3, data a direita, assinaturas centralizadas).
-- So altera o conteudo; nome, categoria e tipo continuam os mesmos.

update public.modelos_contrato set conteudo = $modelo$<p style="text-align: center;"><b>CONTRATO DE LOCAÇÃO DE IMÓVEL</b></p><p><br></p><p style="text-align: justify;"><b>Qualificação das Partes</b></p><p style="text-align: justify;"><span style="font-size: 0.875rem;"><b>LOCADOR(A)</b>: #nome_locador#qualificacao_locador, inscrito(a) no CPF/CNPJ sob o nº #cpf_locador, com endereço em #endereco_locador, e-mail #email_locador, telefone #telefone_locador, doravante denominado(a) simplesmente LOCADOR(A), neste ato representado(a) por sua mandatária, a ADMINISTRADORA abaixo qualificada;</span></p><p style="text-align: justify;"><b>ADMINISTRADORA</b>: #nome_administradora, inscrita no CNPJ sob o nº #cnpj_administradora, registrada no CRECI sob o nº #creci_administradora, com sede em #endereco_administradora, e-mail #email_administradora, telefone #telefone_administradora, neste ato representada por #representante_administradora, inscrito(a) no CPF sob o nº #cpf_representante_administradora, doravante denominada simplesmente ADMINISTRADORA, que comparece por si e na qualidade de mandatária do(a) LOCADOR(A), com os poderes que lhe foram conferidos pelo Contrato de Administração de Imóveis nº #numero_contrato_administracao, firmado em #data_contrato_administracao; e</p><p style="text-align: justify;"><b>LOCATÁRIO(A)</b>: #nome_locatario#qualificacao_locatario, inscrito(a) no CPF/CNPJ sob o nº #cpf_locatario, com endereço em #endereco_locatario, e-mail #email_locatario, telefone #telefone_locatario, doravante denominado(a) simplesmente LOCATÁRIO(A).</p><div style="text-align: justify;"><span style="font-size: 0.875rem;">As partes acima identificadas, por si e por seus representantes legais infra-assinados, celebram o presente Contrato de Locação, regido pelas cláusulas e condições a seguir:</span></div><p style="text-align: justify;"><b>1 - Documentos Contratuais</b></p><p style="text-align: justify;">Integram este instrumento na forma de anexos: a) fatura de energia; b) protocolo de entrega das chaves; c) laudo de vistoria.</p><p style="text-align: justify;"><b>2 - Descrição/Localização do Imóvel e Utilização</b></p><p style="text-align: justify;">O imóvel objeto deste contrato está localizado em #endereco_imovel, classificado como #tipo_imovel, com a seguinte descrição: #descricao_imovel. Destina-se exclusivamente ao uso indicado pelas partes.</p><p><b>3 - Preço, Prazo e Forma de Pagamento</b></p><table style="border-collapse:collapse;width:100%;"><tbody><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Valor mensal:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#valor_aluguel (#valor_aluguel_extenso).</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Vencimento:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">dia #dia_pagamento de cada mês.</span></div></td></tr><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Valor total estimado do contrato:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#valor_total_contrato</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">(#valor_total_contrato_extenso).</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Início do contrato: #data_inicio.</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">Término do contrato: #vigencia_final.</span></div></td></tr><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Duração do contrato:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#duracao_meses_extenso.</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Dados bancários para pagamento:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#dados_bancarios_proprietario.</span></div></td></tr></tbody></table><p style="text-align: justify;"><b>4 - Reajustamento</b></p><p style="text-align: justify;">O aluguel mensal pactuado na Cláusula 3 será reajustado após 12 (doze) meses de vigência, tendo como limite o índice IGP-M, divulgado pela FGV, ou, na sua falta, outro que o substitua.</p><p style="text-align: justify;"><b>5 - Transferência/Cessão</b></p><p style="text-align: justify;">É vedado ao(a)&nbsp;<b>LOCATÁRIO(A)&nbsp;</b>e ao(a)&nbsp;<b>LOCADOR(A)</b>,&nbsp; transferir, sublocar ou emprestar o imóvel, bem como, negociar com terceiros qualquer direitos decorrentes deste Instrumento, em especial, créditos representados por títulos de qualquer natureza, sem prévia, formal e expressa anuência da outra parte, tornando-se nula qualquer operação não autorizada previamente.</p><p style="text-align: justify;"><b>6 - Taxas e impostos</b></p><p style="text-align: justify;">Será de responsabilidade do(a)&nbsp;<b>LOCATÁRIO(A)&nbsp;</b>o pagamento das taxas de energia e água referentes ao período de locação do imóvel, devendo apresentar as guias quitadas ao(a) <b>LOCADOR(A)</b>. O(A) LOCATÁRIO(A) declara ter ciência da obrigação de transferir a titularidade da unidade consumidora de energia junto à <b>EQUATORIAL </b>e à concessionária de água junto á <b>BRK</b>.</p><p style="text-align: justify;"><b>7 - Vistorias</b></p><p style="text-align: justify;">O(A)&nbsp;<b>LOCATÁRIO(A)</b>, declara que vistoriou o imóvel, e que o mesmo está sendo entregue nas condições especificadas no <b>Termo de Vistoria de Imóvel</b>, anexo a este Instrumento, devendo restituí-lo, quando finda a locação, nas mesmas condições em que o recebeu.</p><p style="text-align: justify;"><b>8 - Obras/Manutenção</b></p><p style="text-align: justify;">Salvo as obras que importem na segurança estrutural do imóvel, e demais benfeitorias consideradas necessárias, todas as outras são de responsabilidade do(a) <b>LOCATÁRIO(A)</b>, que deverá manter imóvel em boas condições de higiene e limpeza. O imóvel deverá ser devolvido com a pintura nas mesmas condições encontradas, além de conservar as instalações hidráulicas, sanitárias e elétricas sempre em perfeitas condições de funcionamento para atender às necessidades do(a) <b>LOCADOR(A)</b>. Além disso, a manutenção/reparação e infiltrações no geral ficará por conta do(a) <b>LOCATÁRIO(A)</b>.</p><p style="text-align: justify;"><b>9 - Desapropriação/Interdição</b></p><p style="text-align: justify;">Em caso de desapropriação ou interdição pelo poder público, o(a) <b>LOCADOR(A)</b> fica desobrigada das cláusulas deste contrato, ressalvado ao(a) <b>LOCATÁRIO(A)&nbsp;</b>o direito de pleitear indenização junto ao responsável.</p><p style="text-align: justify;"><b>10 - Venda do imóvel</b></p><p style="text-align: justify;">Em caso de alienação ou venda do imóvel a terceiros, e não exercendo o(a) <b>LOCATÁRIO(A)&nbsp;</b>o seu direito de preferência, esta autorizará a visita de interessados mediante agendamento prévio e compromete-se a desocupar o imóvel no prazo legal de até 90 (noventa) dias contados da notificação formal, sem que isso caracterize infração ou quebra de contrato.</p><p style="text-align: justify;"><b>11 - Devolução antecipada</b></p><p style="text-align: justify;">A devolução antecipada, salvo força maior comprovada, exige aviso prévio de 30 dias e sujeita o(a) <b>LOCATÁRIO(A)</b> a multa equivalente a 3 (três) meses de aluguel, proporcional ao tempo restante do contrato.</p><p style="text-align: justify;">Como calcular: Pega-se o valor total da multa estabelecido no contrato, divide-se pelo número total de meses do acordo e multiplica-se pelos meses restantes para o fim da vigência.</p><p style="text-align: justify;"><b>12 - Forma de pagamento e rescisão</b></p><p style="text-align: justify;">O pagamento seguirá exclusivamente a forma prevista na <b>Cláusula 3</b>. Findo o prazo do contrato sem aditivo de prorrogação, este se extingue; a rescisão por iniciativa do(a) <b>LOCATÁRIO(A)&nbsp;</b>exige os mesmos 30 dias de aviso e multa da <b>Cláusula 11</b>, e por iniciativa do(a) <b>LOCADOR(A)&nbsp;</b>decorre de infração contratual ou inadimplemento.</p><p style="text-align: justify;"><b>13 - Rescisão antecipada e multa proporcional</b>&nbsp;</p><p style="text-align: justify;">O presente contrato possui vigência de&nbsp;#duracao_meses. Caso o(a) <b>LOCATÁRIO(A) </b>resolva rescindir o contrato antes do término do prazo avençado, deverá notificar o(a) <b>LOCADOR(A) </b>ou sua <b>Administradora </b>por escrito e com antecedência mínima de <b>30 (trinta) </b>dias (aviso prévio), ficando sujeito ao pagamento de multa rescisória contratual.</p><p style="text-align: justify;"><span style="font-size: 0.875rem;">A multa contratual integral é fixada no valor equivalente a 3 (três) valor(es) do aluguel vigente à época da infração. Nos termos do artigo 4º da Lei nº 8.245/91, a referida multa será cobrada de forma estritamente proporcional ao tempo restante para o encerramento do contrato, mediante a aplicação da seguinte fórmula matemática: <b>Multa Devida = (Valor da Multa Integral / Prazo Total do Contrato em Meses) X Meses Restantes a Cumprir</b>.</span></p><p style="text-align: justify;">Para fins do cálculo previsto no parágrafo anterior, a fração superior a 15 (quinze) dias no mês de saída será considerada como 1 (um) mês integral a ser contabilizado na proporcionalidade.</p><p style="text-align: justify;">O não cumprimento do aviso prévio de 30 (trinta) dias sujeitará o(a) <b>LOCATÁRIO(A) </b>ao pagamento do valor equivalente a 1 (um) aluguel mensal vigente, <b>cobrado cumulativamente </b>com a multa rescisória proporcional descrita no Parágrafo Primeiro.</p><p style="text-align: justify;">O(A) <b>LOCATÁRIO(A) </b>ficará isento(a) do pagamento da multa rescisória apenas se a devolução do imóvel decorrer de transferência de seu local de trabalho prestado a empregador (público ou privado), para prestar serviços em localidades diversas daquela onde iniciou a locação, mediante notificação por escrito com antecedência mínima de 30 (trinta) dias e apresentação de comprovante oficial expedido pelo empregador.</p><p style="text-align: justify;"><b>14 - Dos encargos por atraso no pagamento</b></p><p style="text-align: justify;">Em caso de atraso no pagamento do aluguel e/ou encargos até a data estipulada no vencimento, o valor devido será acrescido de multa moratória de 2% (dois por cento) sobre o valor do débito, somado a juros de mora de 1% (um por cento) ao mês, calculados pro rata die até a data do efetivo pagamento. A presente cobrança possui fundamento legal na obrigação do locatário de pagar pontualmente o aluguel e os encargos da locação, nos termos do Art. 23, inciso I, da Lei Federal nº 8.245/1991 (Lei do Inquilinato), sujeitando o devedor às penalidades da mora.</p><p style="text-align: justify;"><b>15 -&nbsp; Da vistoria e visita trimestral</b></p><p style="text-align: justify;">Fica resguardado ao <b>LOCADOR </b>e/ou à Imobiliária administradora o direito de realizar visitas e vistorias periódicas a cada trimestre (3 meses) no imóvel locado, mediante prévio agendamento com a devida antecedência, com o objetivo de verificar o estado de conservação, manutenção das instalações e o cumprimento das obrigações contratuais, conforme respaldado no Art. 23, inciso IX, da Lei nº 8.245/1991.</p><p style="text-align: justify;"><b>16 - Devolução das chaves</b></p><p style="text-align: justify;">A entrega das chaves ocorrerá após vistoria de saída comparada ao laudo inicial, mediante apresentação dos comprovantes de quitação de contas e cancelamento de serviços vinculados ao imóvel, devolvido limpo, pintado na cor original e sem reparos pendentes; havendo reparos necessários não realizados, o(a) <b>LOCADOR(A)</b> poderá recusar a devolução até sua conclusão, prevalecendo, em caso de desacordo, laudo de perito por ela indicado, a expensas do <b>LOCATÁRIO(A)</b>.</p><p style="text-align: justify;"><b>17 - Da Administradora</b></p><p style="text-align: justify;">A <b>ADMINISTRADORA</b> atua neste contrato exclusivamente na qualidade de mandatária do(a) <b>LOCADOR(A)</b>, nos termos do Contrato de Administração de Imóveis referido na qualificação das partes, praticando em nome deste(a) os atos de administração da presente locação, e não responde pessoalmente pelas obrigações atribuídas ao(à) <b>LOCADOR(A)</b> neste instrumento, na forma do art. 663 do Código Civil.</p><p style="text-align: justify;"><b>Parágrafo primeiro.</b> Todas as comunicações, notificações, avisos e pedidos relativos a esta locação, inclusive o aviso prévio de desocupação e os pedidos de autorização previstos neste contrato, deverão ser dirigidos por escrito à <b>ADMINISTRADORA</b>, valendo como se feitos ao(à) <b>LOCADOR(A)</b>.</p><p style="text-align: justify;"><b>Parágrafo segundo.</b> Compete à <b>ADMINISTRADORA</b>, em nome do(a) <b>LOCADOR(A)</b>, realizar as vistorias de entrada, periódicas e de saída, entregar e receber as chaves, autorizar ou recusar obras, benfeitorias e a permanência de terceiros no imóvel, bem como exercer os demais direitos atribuídos ao(à) <b>LOCADOR(A)</b> neste instrumento.</p><p style="text-align: justify;"><b>Parágrafo terceiro.</b> Extinto o Contrato de Administração, o(a) <b>LOCADOR(A)</b> ou a <b>ADMINISTRADORA</b> comunicará o fato por escrito ao(à) <b>LOCATÁRIO(A)</b>. A partir do recebimento dessa comunicação, a presente locação prossegue diretamente entre <b>LOCADOR(A)</b> e <b>LOCATÁRIO(A)</b>, nas mesmas condições, cessando a participação da <b>ADMINISTRADORA</b>, e as comunicações passam a ser dirigidas ao(à) <b>LOCADOR(A)</b> no endereço constante deste contrato ou no que vier a ser informado por escrito.</p><p style="text-align: justify;"><b>18 - Boa-fé</b></p><p style="text-align: justify;">As partes declaram pleno conhecimento das cláusulas deste contrato e comprometem-se a agir com lealdade e boa-fé, desde a celebração até a integral execução deste instrumento.</p><p style="text-align: justify;"><b>19 - Disposições Finais</b></p><p></p><div style="text-align: justify;"><span style="font-size: 0.875rem;">As partes elegem expressamente o Foro da Comarca de Curionópolis, Estado do Pará, com renúncia a qualquer outro, por mais privilegiado que seja, para dirimir quaisquer dúvidas, litígios ou ações oriundas da interpretação ou execução deste contrato.</span></div><div style="text-align: justify;"><br></div><p></p><div style="text-align: right;"><span style="font-size: 0.875rem;">Curionópolis, Pará, #data_hoje.</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">por si e como procuradora de #nome_locador</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">CNPJ #cnpj_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">ADMINISTRADORA, por si e representando o(a) LOCADOR(A)</span></div><div style="text-align: center;"><br></div><div style="text-align: center;"><br></div><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_locatario</span></div><div style="text-align: center;"><span style="text-align: start;">#cpf_locatario</span><span style="font-size: 0.875rem;"></span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">LOCATÁRIO(A)</span></div><p></p>$modelo$
where nome = 'CONTRATO DE LOCAÇÃO DE IMÓVEL - ADMINISTRAÇÃO (COM ADMINISTRADORA)';

update public.modelos_contrato set conteudo = $modelo$<p style="text-align: center;"><b>CONTRATO DE LOCAÇÃO DE IMÓVEL</b></p><p><br></p><p style="text-align: justify;"><b>Qualificação das Partes</b></p><p style="text-align: justify;"><span style="font-size: 0.875rem;"><b>LOCADOR(A)</b>: #nome_locador#qualificacao_locador, inscrito(a) no CPF/CNPJ sob o nº #cpf_locador, com endereço em #endereco_locador, e-mail #email_locador, telefone #telefone_locador, doravante denominado(a) simplesmente LOCADOR(A), neste ato representado(a) por sua mandatária, a ADMINISTRADORA abaixo qualificada;</span></p><p style="text-align: justify;"><b>ADMINISTRADORA</b>: #nome_administradora, inscrita no CNPJ sob o nº #cnpj_administradora, registrada no CRECI sob o nº #creci_administradora, com sede em #endereco_administradora, e-mail #email_administradora, telefone #telefone_administradora, neste ato representada por #representante_administradora, inscrito(a) no CPF sob o nº #cpf_representante_administradora, doravante denominada simplesmente ADMINISTRADORA, que comparece por si e na qualidade de mandatária do(a) LOCADOR(A), com os poderes que lhe foram conferidos pelo Contrato de Administração de Imóveis nº #numero_contrato_administracao, firmado em #data_contrato_administracao; e</p><p style="text-align: justify;"><b>LOCATÁRIO(A)</b>: #nome_locatario#qualificacao_locatario, inscrito(a) no CPF/CNPJ sob o nº #cpf_locatario, com endereço em #endereco_locatario, e-mail #email_locatario, telefone #telefone_locatario, doravante denominado(a) simplesmente LOCATÁRIO(A).</p><div style="text-align: justify;"><span style="font-size: 0.875rem;">As partes acima identificadas, por si e por seus representantes legais infra-assinados, celebram o presente Contrato de Locação, regido pelas cláusulas e condições a seguir:</span></div><p style="text-align: justify;"><b>1 - Documentos Contratuais</b></p><p style="text-align: justify;">Integram este instrumento na forma de anexos: a) fatura de energia; b) protocolo de entrega das chaves; c) laudo de vistoria.</p><p style="text-align: justify;"><b>2 - Descrição/Localização do Imóvel e Utilização</b></p><p style="text-align: justify;">O imóvel objeto deste contrato está localizado em #endereco_imovel, classificado como #tipo_imovel, com a seguinte descrição: #descricao_imovel. Destina-se exclusivamente ao uso indicado pelas partes.</p><p><b>3 - Preço, Prazo e Forma de Pagamento</b></p><table style="border-collapse:collapse;width:100%;"><tbody><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Valor mensal:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#valor_aluguel (#valor_aluguel_extenso).</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Vencimento:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">dia #dia_pagamento de cada mês.</span></div></td></tr><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Valor total estimado do contrato:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#valor_total_contrato</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">(#valor_total_contrato_extenso).</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Início do contrato: #data_inicio.</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">Término do contrato: #vigencia_final.</span></div></td></tr><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Duração do contrato:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#duracao_meses_extenso.</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Dados bancários para pagamento:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#dados_bancarios_proprietario.</span></div></td></tr></tbody></table><p style="text-align: justify;"><b>4 - Reajustamento</b></p><p style="text-align: justify;">O aluguel mensal pactuado na Cláusula 3 será reajustado após 12 (doze) meses de vigência, tendo como limite o índice IGP-M, divulgado pela FGV, ou, na sua falta, outro que o substitua.</p><p style="text-align: justify;"><b>5 - Transferência/Cessão</b></p><p style="text-align: justify;">É vedado ao(a)&nbsp;<b>LOCATÁRIO(A)&nbsp;</b>e ao(a)&nbsp;<b>LOCADOR(A)</b>,&nbsp; transferir, sublocar ou emprestar o imóvel, bem como, negociar com terceiros qualquer direitos decorrentes deste Instrumento, em especial, créditos representados por títulos de qualquer natureza, sem prévia, formal e expressa anuência da outra parte, tornando-se nula qualquer operação não autorizada previamente.</p><p style="text-align: justify;">A permanência de visitantes ou hóspedes na kitnet é permitida apenas em caráter estritamente temporário.</p><p style="text-align: justify;"><span style="font-size: 0.875rem;">Entende-se por hospedagem temporária a estadia ininterrupta de terceiros por até 15 dias. Caso a permanência do visitante ultrapasse esse prazo sem notificação e autorização prévia da <b>Administradora</b>, a situação será caracterizada como sublocação/cessão irregular da locação ou inclusão de novo morador não autorizado.</span></p><p style="text-align: justify;"><span style="font-size: 0.875rem;">Constatada a permanência habitacional não autorizada de terceiros, a Administradora poderá aplicar multa por infração contratual e readequar a taxa de consumo de água e energia (caso estas sejam cobradas de forma compartilhada ou inclusas no valor do aluguel), sem prejuízo da rescisão imediata do contrato.</span></p><p style="text-align: justify;"><b>6 - Taxas e impostos</b></p><p style="text-align: justify;">Será de responsabilidade do(a)&nbsp;<b>LOCATÁRIO(A)&nbsp;</b>o pagamento das taxas de energia e água referentes ao período de locação do imóvel, devendo apresentar as guias quitadas ao(a) <b>LOCADOR(A)</b>. O(A) LOCATÁRIO(A) declara ter ciência da obrigação de transferir a titularidade da unidade consumidora de energia junto à <b>EQUATORIAL </b>e à concessionária de água junto á <b>BRK</b>.</p><p style="text-align: justify;"><b>7 - Vistorias</b></p><p style="text-align: justify;">O(A)&nbsp;<b>LOCATÁRIO(A)</b>, declara que vistoriou o imóvel, e que o mesmo está sendo entregue nas condições especificadas no <b>Termo de Vistoria de Imóvel</b>, anexo a este Instrumento, devendo restituí-lo, quando finda a locação, nas mesmas condições em que o recebeu.</p><p style="text-align: justify;"><b>8 - Obras/Manutenção</b></p><p style="text-align: justify;">Salvo as obras que importem na segurança estrutural do imóvel, e demais benfeitorias consideradas necessárias, todas as outras são de responsabilidade do(a) <b>LOCATÁRIO(A)</b>, que deverá manter imóvel em boas condições de higiene e limpeza. O imóvel deverá ser devolvido com a pintura nas mesmas condições encontradas, além de conservar as instalações hidráulicas, sanitárias e elétricas sempre em perfeitas condições de funcionamento para atender às necessidades do(a) <b>LOCADOR(A)</b>. Além disso, a manutenção/reparação e infiltrações no geral ficará por conta do(a) <b>LOCATÁRIO(A)</b>.</p><p style="text-align: justify;"><b>9 - Desapropriação/Interdição</b></p><p style="text-align: justify;">Em caso de desapropriação ou interdição pelo poder público, o(a) <b>LOCADOR(A)</b> fica desobrigada das cláusulas deste contrato, ressalvado ao(a) <b>LOCATÁRIO(A)&nbsp;</b>o direito de pleitear indenização junto ao responsável.</p><p style="text-align: justify;"><b>10 - Venda do imóvel</b></p><p style="text-align: justify;">Em caso de alienação ou venda do imóvel a terceiros, e não exercendo o(a) <b>LOCATÁRIO(A)&nbsp;</b>o seu direito de preferência, esta autorizará a visita de interessados mediante agendamento prévio e compromete-se a desocupar o imóvel no prazo legal de até 90 (noventa) dias contados da notificação formal, sem que isso caracterize infração ou quebra de contrato.</p><p style="text-align: justify;"><b>11 - Devolução antecipada</b></p><p style="text-align: justify;">A devolução antecipada, salvo força maior comprovada, exige aviso prévio de 30 dias e sujeita o(a) <b>LOCATÁRIO(A)</b> a multa equivalente a 3 (três) meses de aluguel, proporcional ao tempo restante do contrato.</p><p style="text-align: justify;">Como calcular: Pega-se o valor total da multa estabelecido no contrato, divide-se pelo número total de meses do acordo e multiplica-se pelos meses restantes para o fim da vigência.</p><p style="text-align: justify;"><b>12 - Forma de pagamento e rescisão</b></p><p style="text-align: justify;">O pagamento seguirá exclusivamente a forma prevista na <b>Cláusula 3</b>. Findo o prazo do contrato sem aditivo de prorrogação, este se extingue; a rescisão por iniciativa do(a) <b>LOCATÁRIO(A)&nbsp;</b>exige os mesmos 30 dias de aviso e multa da <b>Cláusula 11</b>, e por iniciativa do(a) <b>LOCADOR(A)&nbsp;</b>decorre de infração contratual ou inadimplemento.</p><p style="text-align: justify;"><b>13 - Rescisão antecipada e multa proporcional</b>&nbsp;</p><p style="text-align: justify;">O presente contrato possui vigência de&nbsp;#duracao_meses. Caso o(a) <b>LOCATÁRIO(A) </b>resolva rescindir o contrato antes do término do prazo avençado, deverá notificar o(a) <b>LOCADOR(A) </b>ou sua <b>Administradora </b>por escrito e com antecedência mínima de <b>30 (trinta) </b>dias (aviso prévio), ficando sujeito ao pagamento de multa rescisória contratual.</p><p style="text-align: justify;"><span style="font-size: 0.875rem;">A multa contratual integral é fixada no valor equivalente a 3 (três) valor(es) do aluguel vigente à época da infração. Nos termos do artigo 4º da Lei nº 8.245/91, a referida multa será cobrada de forma estritamente proporcional ao tempo restante para o encerramento do contrato, mediante a aplicação da seguinte fórmula matemática: <b>Multa Devida = (Valor da Multa Integral / Prazo Total do Contrato em Meses) X Meses Restantes a Cumprir</b>.</span></p><p style="text-align: justify;">Para fins do cálculo previsto no parágrafo anterior, a fração superior a 15 (quinze) dias no mês de saída será considerada como 1 (um) mês integral a ser contabilizado na proporcionalidade.</p><p style="text-align: justify;">O não cumprimento do aviso prévio de 30 (trinta) dias sujeitará o(a) <b>LOCATÁRIO(A) </b>ao pagamento do valor equivalente a 1 (um) aluguel mensal vigente, <b>cobrado cumulativamente </b>com a multa rescisória proporcional descrita no Parágrafo Primeiro.</p><p style="text-align: justify;">O(A) <b>LOCATÁRIO(A) </b>ficará isento(a) do pagamento da multa rescisória apenas se a devolução do imóvel decorrer de transferência de seu local de trabalho prestado a empregador (público ou privado), para prestar serviços em localidades diversas daquela onde iniciou a locação, mediante notificação por escrito com antecedência mínima de 30 (trinta) dias e apresentação de comprovante oficial expedido pelo empregador.</p><p style="text-align: justify;"><b>14 - Dos encargos por atraso no pagamento</b></p><p style="text-align: justify;">Em caso de atraso no pagamento do aluguel e/ou encargos até a data estipulada no vencimento, o valor devido será acrescido de multa moratória de 2% (dois por cento) sobre o valor do débito, somado a juros de mora de 1% (um por cento) ao mês, calculados pro rata die até a data do efetivo pagamento. A presente cobrança possui fundamento legal na obrigação do locatário de pagar pontualmente o aluguel e os encargos da locação, nos termos do Art. 23, inciso I, da Lei Federal nº 8.245/1991 (Lei do Inquilinato), sujeitando o devedor às penalidades da mora.</p><p style="text-align: justify;"><b>15 - Das regras de convivência e regimento interno</b></p><p style="text-align: justify;">Por se tratar de imóvel integrante de um conjunto/complexo de residências multifamiliares com uso de áreas comuns (corredores, acessos, lavanderias ou pátios), <b>o(a) LOCATÁRIO(A) </b>compromete-se a cumprir e fazer cumprir rigorosamente as seguintes normas de boa convivência:</p><p style="text-align: justify;"><span style="font-size: 0.875rem;"><b>Silêncio</b>: Respeitar o horário de silêncio obrigatório das 22h00 às 07h00, sendo proibido o uso de aparelhos sonoros, instrumentos musicais ou ruídos em volume que perturbem o sossego dos demais vizinhos;</span></p><p style="text-align: justify;"><span style="font-size: 0.875rem;"><b>Uso de Áreas Comuns</b>: É expressamente proibido depositar móveis, entulhos, lixo, bicicletas ou quaisquer objetos pessoais nos corredores, passagens e áreas de circulação comum;</span></p><p style="text-align: justify;"><b style="font-size: 0.875rem;">Festas e Eventos: </b><span style="font-size: 0.875rem;">É vedada a realização de festas, reuniões ruidosas ou aglomerações nas áreas comuns do condomínio/vila de kitnets.</span></p><p style="text-align: justify;"><span style="font-size: 0.875rem;">O descumprimento comprovado de qualquer uma das regras de convivência aqui listadas sujeitará o(a) <b>LOCATÁRIO(A) </b>à advertência por escrito e, em caso de reincidência, à aplicação de multa no valor equivalente a 50% (cinquenta por cento) do valor do aluguel mensal, podendo ensejar a rescisão motivada do contrato de locação por infração contratual.</span></p><p style="text-align: justify;"><b>16 -&nbsp; Da vistoria e visita trimestral</b></p><p style="text-align: justify;">Fica resguardado ao <b>LOCADOR </b>e/ou à Imobiliária administradora o direito de realizar visitas e vistorias periódicas a cada trimestre (3 meses) no imóvel locado, mediante prévio agendamento com a devida antecedência, com o objetivo de verificar o estado de conservação, manutenção das instalações e o cumprimento das obrigações contratuais, conforme respaldado no Art. 23, inciso IX, da Lei nº 8.245/1991.</p><p style="text-align: justify;"><b>17 - Devolução das chaves</b></p><p style="text-align: justify;">A entrega das chaves ocorrerá após vistoria de saída comparada ao laudo inicial, mediante apresentação dos comprovantes de quitação de contas e cancelamento de serviços vinculados ao imóvel, devolvido limpo, pintado na cor original e sem reparos pendentes; havendo reparos necessários não realizados, o(a) <b>LOCADOR(A)</b> poderá recusar a devolução até sua conclusão, prevalecendo, em caso de desacordo, laudo de perito por ela indicado, a expensas do <b>LOCATÁRIO(A)</b>.</p><p style="text-align: justify;"><b>18 - Da Administradora</b></p><p style="text-align: justify;">A <b>ADMINISTRADORA</b> atua neste contrato exclusivamente na qualidade de mandatária do(a) <b>LOCADOR(A)</b>, nos termos do Contrato de Administração de Imóveis referido na qualificação das partes, praticando em nome deste(a) os atos de administração da presente locação, e não responde pessoalmente pelas obrigações atribuídas ao(à) <b>LOCADOR(A)</b> neste instrumento, na forma do art. 663 do Código Civil.</p><p style="text-align: justify;"><b>Parágrafo primeiro.</b> Todas as comunicações, notificações, avisos e pedidos relativos a esta locação, inclusive o aviso prévio de desocupação e os pedidos de autorização previstos neste contrato, deverão ser dirigidos por escrito à <b>ADMINISTRADORA</b>, valendo como se feitos ao(à) <b>LOCADOR(A)</b>.</p><p style="text-align: justify;"><b>Parágrafo segundo.</b> Compete à <b>ADMINISTRADORA</b>, em nome do(a) <b>LOCADOR(A)</b>, realizar as vistorias de entrada, periódicas e de saída, entregar e receber as chaves, autorizar ou recusar obras, benfeitorias e a permanência de terceiros no imóvel, bem como exercer os demais direitos atribuídos ao(à) <b>LOCADOR(A)</b> neste instrumento.</p><p style="text-align: justify;"><b>Parágrafo terceiro.</b> Extinto o Contrato de Administração, o(a) <b>LOCADOR(A)</b> ou a <b>ADMINISTRADORA</b> comunicará o fato por escrito ao(à) <b>LOCATÁRIO(A)</b>. A partir do recebimento dessa comunicação, a presente locação prossegue diretamente entre <b>LOCADOR(A)</b> e <b>LOCATÁRIO(A)</b>, nas mesmas condições, cessando a participação da <b>ADMINISTRADORA</b>, e as comunicações passam a ser dirigidas ao(à) <b>LOCADOR(A)</b> no endereço constante deste contrato ou no que vier a ser informado por escrito.</p><p style="text-align: justify;"><b>19 - Boa-fé</b></p><p style="text-align: justify;">As partes declaram pleno conhecimento das cláusulas deste contrato e comprometem-se a agir com lealdade e boa-fé, desde a celebração até a integral execução deste instrumento.</p><p style="text-align: justify;"><b>20 - Disposições Finais</b></p><p></p><div style="text-align: justify;"><span style="font-size: 0.875rem;">As partes elegem expressamente o Foro da Comarca de Curionópolis, Estado do Pará, com renúncia a qualquer outro, por mais privilegiado que seja, para dirimir quaisquer dúvidas, litígios ou ações oriundas da interpretação ou execução deste contrato.</span></div><div style="text-align: justify;"><br></div><p></p><div style="text-align: right;"><span style="font-size: 0.875rem;">Curionópolis, Pará, #data_hoje.</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">por si e como procuradora de #nome_locador</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">CNPJ #cnpj_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">ADMINISTRADORA, por si e representando o(a) LOCADOR(A)</span></div><div style="text-align: center;"><br></div><div style="text-align: center;"><br></div><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_locatario</span></div><div style="text-align: center;"><span style="text-align: start;">#cpf_locatario</span><span style="font-size: 0.875rem;"></span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">LOCATÁRIO(A)</span></div><p></p>$modelo$
where nome = 'CONTRATO DE LOCAÇÃO DE IMÓVEL - KITNET (COM ADMINISTRADORA)';

update public.modelos_contrato set conteudo = $modelo$<p style="text-align: center;"><b>CONTRATO DE ADMINISTRAÇÃO DE IMÓVEIS COM OUTORGA DE MANDATO</b></p><p style="text-align: center;"><b>Nº #numero_contrato_administracao</b></p><p style="text-align: justify;"><br></p><p style="text-align: justify;"><b>Qualificação das Partes</b></p><p style="text-align: justify;"><b>PROPRIETÁRIO(A)</b>: #nome_proprietario#qualificacao_proprietario, inscrito(a) no CPF/CNPJ sob o nº #cpf_cnpj_proprietario, com endereço em #endereco_proprietario, e-mail #email_proprietario, telefone #telefone_proprietario, doravante denominado(a) simplesmente PROPRIETÁRIO(A); e</p><p style="text-align: justify;"><b>ADMINISTRADORA</b>: #nome_administradora, inscrita no CNPJ sob o nº #cnpj_administradora, registrada no CRECI sob o nº #creci_administradora, com sede em #endereco_administradora, e-mail #email_administradora, telefone #telefone_administradora, neste ato representada por #representante_administradora, inscrito(a) no CPF sob o nº #cpf_representante_administradora, doravante denominada simplesmente ADMINISTRADORA.</p><p style="text-align: justify;">As partes acima identificadas celebram o presente Contrato de Administração de Imóveis, com outorga de mandato, regido pelos artigos 653 e seguintes do Código Civil e pelas cláusulas e condições a seguir:</p><p style="text-align: justify;"><b>1 - Objeto</b></p><p style="text-align: justify;">O(A) PROPRIETÁRIO(A) confia à ADMINISTRADORA a administração da locação dos seguintes imóveis de sua propriedade: #imoveis_administrados.</p><p style="text-align: justify;"><b>Parágrafo único.</b> Outros imóveis do(a) PROPRIETÁRIO(A) poderão ser incluídos nesta administração mediante termo aditivo, aplicando-se a eles todas as condições deste contrato.</p><p style="text-align: justify;"><b>2 - Do mandato e dos poderes</b></p><p style="text-align: justify;">Para a execução deste contrato, o(a) PROPRIETÁRIO(A) nomeia e constitui a ADMINISTRADORA sua bastante procuradora, conferindo-lhe poderes especiais e expressos para, em seu nome e por sua conta, em relação aos imóveis administrados:</p><p style="text-align: justify;">a) anunciar, divulgar e mostrar os imóveis a interessados;</p><p style="text-align: justify;">b) selecionar locatários, analisar cadastros e exigir garantias locatícias;</p><p style="text-align: justify;">c) negociar as condições da locação e celebrar, assinar, prorrogar, aditar, renovar e rescindir contratos de locação, termos de vistoria e demais instrumentos a eles relacionados;</p><p style="text-align: justify;">d) receber valores e dar quitação, quando o contrato de locação previr o pagamento à ADMINISTRADORA;</p><p style="text-align: justify;">e) expedir e receber notificações, avisos e comunicações relativas às locações;</p><p style="text-align: justify;">f) realizar vistorias de entrada, periódicas e de saída, entregar e receber chaves e autorizar ou recusar obras, benfeitorias e a permanência de terceiros nos imóveis;</p><p style="text-align: justify;">g) representar o(a) PROPRIETÁRIO(A) perante concessionárias de serviços públicos, condomínios, repartições públicas e cartórios, no que se refira às locações;</p><p style="text-align: justify;">h) promover a cobrança extrajudicial de aluguéis e encargos em atraso.</p><p style="text-align: justify;"><b>3 - Da cobrança judicial</b></p><p style="text-align: justify;">Havendo necessidade de medida judicial relativa às locações, como ação de despejo, cobrança, execução, consignação, revisional ou renovatória, a ADMINISTRADORA indicará advogado de sua confiança, ao qual o(a) PROPRIETÁRIO(A) outorgará procuração com os poderes da cláusula ad judicia. Os honorários contratuais do advogado serão ajustados à parte, diretamente entre o(a) PROPRIETÁRIO(A) e o profissional, e os honorários de sucumbência pertencem ao advogado, nos termos do art. 23 da Lei nº 8.906/1994.</p><p style="text-align: justify;"><b>4 - Da remuneração</b></p><p style="text-align: justify;">Pela administração, a ADMINISTRADORA fará jus a taxa mensal de #taxa_administracao (#taxa_administracao_extenso) sobre o valor do aluguel de cada imóvel locado, devida durante todo o período em que o imóvel permanecer locado por intermédio desta administração. Não há cobrança de taxa enquanto o imóvel estiver desocupado.</p><p style="text-align: justify;"><b>Parágrafo primeiro.</b> O aluguel é pago pelo(a) LOCATÁRIO(A) diretamente ao(à) PROPRIETÁRIO(A), que repassará a taxa à ADMINISTRADORA na data de vencimento do aluguel do respectivo mês, prevista no contrato de locação.</p><p style="text-align: justify;"><b>Parágrafo segundo.</b> Quando o contrato de locação previr o pagamento do aluguel à ADMINISTRADORA, esta reterá a taxa e repassará o saldo ao(à) PROPRIETÁRIO(A) após a compensação do pagamento.</p><p style="text-align: justify;"><b>5 - Da ausência de garantia</b></p><p style="text-align: justify;">A ADMINISTRADORA não garante o pagamento de aluguéis, encargos ou indenizações devidos pelos locatários, nem responde pela inadimplência ou por danos por eles causados aos imóveis, obrigando-se a empregar diligência na cobrança e na adoção das medidas previstas neste contrato.</p><p style="text-align: justify;"><b>6 - Das obrigações do(a) PROPRIETÁRIO(A)</b></p><p style="text-align: justify;">Compete ao(à) PROPRIETÁRIO(A): a) informar à ADMINISTRADORA o recebimento dos aluguéis pagos diretamente a ele(a), bem como eventual atraso, para permitir a cobrança; b) arcar com os tributos e despesas que lhe cabem por lei, especialmente os previstos no art. 22 da Lei nº 8.245/1991; c) comunicar por escrito qualquer alteração de seus dados cadastrais ou bancários.</p><p style="text-align: justify;"><b>7 - Da exclusividade</b></p><p style="text-align: justify;">Durante a vigência deste contrato, o(a) PROPRIETÁRIO(A) não poderá locar os imóveis administrados diretamente ou por intermédio de terceiros, nem confiar sua administração a outra pessoa ou empresa.</p><p style="text-align: justify;"><b>8 - Do prazo e da extinção</b></p><p style="text-align: justify;">Este contrato vigora por prazo indeterminado, a partir de #data_contrato_administracao, e pode ser denunciado por qualquer das partes mediante aviso por escrito com antecedência mínima de 30 (trinta) dias, sem multa ou indenização.</p><p style="text-align: justify;"><b>Parágrafo único.</b> Extinto este contrato, cessam a taxa de administração e a participação da ADMINISTRADORA nas locações em curso, que prosseguirão diretamente entre o(a) PROPRIETÁRIO(A) e os locatários. A ADMINISTRADORA comunicará a extinção aos locatários por escrito e entregará ao(à) PROPRIETÁRIO(A) os contratos, chaves e documentos em seu poder.</p><p style="text-align: justify;"><b>9 - Do foro</b></p><p style="text-align: justify;">As partes elegem expressamente o Foro da Comarca de Curionópolis, Estado do Pará, com renúncia a qualquer outro, por mais privilegiado que seja, para dirimir quaisquer dúvidas, litígios ou ações oriundas da interpretação ou execução deste contrato.</p><div style="text-align: right;"><span style="font-size: 0.875rem;">Curionópolis, Pará, #data_hoje.</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_proprietario</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#cpf_cnpj_proprietario</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">PROPRIETÁRIO(A)</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">CNPJ #cnpj_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">ADMINISTRADORA</span></div>$modelo$
where nome = 'CONTRATO DE ADMINISTRAÇÃO DE IMÓVEIS';

update public.modelos_contrato set conteudo = $modelo$<p style="text-align: center;"><b>TERMO ADITIVO Nº #numero_aditivo AO CONTRATO DE LOCAÇÃO DE IMÓVEL Nº #numero_contrato</b></p><p style="text-align: justify;"><br></p><p style="text-align: justify;"><b>Qualificação das Partes</b></p><p style="text-align: justify;"><b>LOCADOR(A)</b>: #nome_locador#qualificacao_locador, inscrito(a) no CPF/CNPJ sob o nº #cpf_locador, com endereço em #endereco_locador, doravante denominado(a) simplesmente LOCADOR(A), neste ato representado(a) por sua mandatária, a ADMINISTRADORA abaixo qualificada;</p><p style="text-align: justify;"><b>ADMINISTRADORA</b>: #nome_administradora, inscrita no CNPJ sob o nº #cnpj_administradora, registrada no CRECI sob o nº #creci_administradora, com sede em #endereco_administradora, neste ato representada por #representante_administradora, inscrito(a) no CPF sob o nº #cpf_representante_administradora, doravante denominada simplesmente ADMINISTRADORA, que comparece por si e na qualidade de mandatária do(a) LOCADOR(A), com os poderes que lhe foram conferidos pelo Contrato de Administração de Imóveis nº #numero_contrato_administracao, firmado em #data_contrato_administracao; e</p><p style="text-align: justify;"><b>LOCATÁRIO(A)</b>: #nome_locatario#qualificacao_locatario, inscrito(a) no CPF/CNPJ sob o nº #cpf_locatario, com endereço em #endereco_locatario, doravante denominado(a) simplesmente LOCATÁRIO(A).</p><p style="text-align: justify;">As partes acima identificadas resolvem aditar o Contrato de Locação de Imóvel nº #numero_contrato, referente ao imóvel situado em #endereco_imovel, mediante as cláusulas e condições a seguir:</p><p style="text-align: justify;"><b>1 - Da retificação das partes</b></p><p style="text-align: justify;">Fica retificada a qualificação das partes do contrato original, para constar que figura como LOCADOR(A) o(a) proprietário(a) do imóvel, #nome_locador, acima qualificado(a), e que #nome_administradora participa da locação exclusivamente como ADMINISTRADORA e mandatária do(a) LOCADOR(A), e não como locadora. As menções do contrato original à imobiliária como locadora passam a ser entendidas como feitas ao(à) LOCADOR(A), representado(a) pela ADMINISTRADORA.</p><p style="text-align: justify;"><b>2 - Da prorrogação e do aluguel</b></p><p style="text-align: justify;">O prazo da locação fica prorrogado e o aluguel passa a vigorar nas condições abaixo:</p><table style="border-collapse:collapse;width:100%;"><tbody><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Início da prorrogação:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#data_inicio.</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Término:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#vigencia_final.</span></div></td></tr><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Duração:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#duracao_meses_extenso.</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Vencimento:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">dia #dia_pagamento de cada mês.</span></div></td></tr><tr><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Valor mensal:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#valor_aluguel (#valor_aluguel_extenso).</span></div></td><td style="border:1px solid #94a3b8;padding:6px 8px;min-width:60px;"><div style="text-align: center;"><span style="font-size: 0.875rem;">Forma de pagamento:</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">mantida a prevista no contrato.</span></div></td></tr></tbody></table><p style="text-align: justify;"><b>3 - Da Administradora</b></p><p style="text-align: justify;">Ficam incluídas no contrato as seguintes disposições:</p><p style="text-align: justify;">A <b>ADMINISTRADORA</b> atua no contrato exclusivamente na qualidade de mandatária do(a) <b>LOCADOR(A)</b>, nos termos do Contrato de Administração de Imóveis referido na qualificação das partes, praticando em nome deste(a) os atos de administração da locação, e não responde pessoalmente pelas obrigações atribuídas ao(à) <b>LOCADOR(A)</b>, na forma do art. 663 do Código Civil.</p><p style="text-align: justify;"><b>Parágrafo primeiro.</b> Todas as comunicações, notificações, avisos e pedidos relativos à locação, inclusive o aviso prévio de desocupação e os pedidos de autorização previstos no contrato, deverão ser dirigidos por escrito à <b>ADMINISTRADORA</b>, valendo como se feitos ao(à) <b>LOCADOR(A)</b>.</p><p style="text-align: justify;"><b>Parágrafo segundo.</b> Compete à <b>ADMINISTRADORA</b>, em nome do(a) <b>LOCADOR(A)</b>, realizar as vistorias de entrada, periódicas e de saída, entregar e receber as chaves, autorizar ou recusar obras, benfeitorias e a permanência de terceiros no imóvel, bem como exercer os demais direitos atribuídos ao(à) <b>LOCADOR(A)</b> no contrato.</p><p style="text-align: justify;"><b>Parágrafo terceiro.</b> Extinto o Contrato de Administração, o(a) <b>LOCADOR(A)</b> ou a <b>ADMINISTRADORA</b> comunicará o fato por escrito ao(à) <b>LOCATÁRIO(A)</b>. A partir do recebimento dessa comunicação, a locação prossegue diretamente entre <b>LOCADOR(A)</b> e <b>LOCATÁRIO(A)</b>, nas mesmas condições, cessando a participação da <b>ADMINISTRADORA</b>, e as comunicações passam a ser dirigidas ao(à) <b>LOCADOR(A)</b> no endereço constante do contrato ou no que vier a ser informado por escrito.</p><p style="text-align: justify;"><b>4 - Da ratificação</b></p><p style="text-align: justify;">Permanecem em vigor todas as demais cláusulas e condições do contrato original que não tenham sido alteradas por este termo aditivo.</p><div style="text-align: right;"><span style="font-size: 0.875rem;">Curionópolis, Pará, #data_hoje.</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">por si e como procuradora de #nome_locador</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">CNPJ #cnpj_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">ADMINISTRADORA, por si e representando o(a) LOCADOR(A)</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_locatario</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#cpf_locatario</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">LOCATÁRIO(A)</span></div>$modelo$
where nome = 'TERMO ADITIVO DE RENOVAÇÃO - LOCAÇÃO ADMINISTRADA';

update public.modelos_contrato set conteudo = $modelo$<p style="text-align: center;"><b>TERMO ADITIVO AO CONTRATO DE ADMINISTRAÇÃO DE IMÓVEIS Nº #numero_contrato_administracao</b></p><p style="text-align: center;"><b>INCLUSÃO DE IMÓVEL</b></p><p style="text-align: justify;"><br></p><p style="text-align: justify;"><b>Qualificação das Partes</b></p><p style="text-align: justify;"><b>PROPRIETÁRIO(A)</b>: #nome_proprietario#qualificacao_proprietario, inscrito(a) no CPF/CNPJ sob o nº #cpf_cnpj_proprietario, com endereço em #endereco_proprietario, doravante denominado(a) simplesmente PROPRIETÁRIO(A); e</p><p style="text-align: justify;"><b>ADMINISTRADORA</b>: #nome_administradora, inscrita no CNPJ sob o nº #cnpj_administradora, registrada no CRECI sob o nº #creci_administradora, com sede em #endereco_administradora, neste ato representada por #representante_administradora, inscrito(a) no CPF sob o nº #cpf_representante_administradora, doravante denominada simplesmente ADMINISTRADORA.</p><p style="text-align: justify;">As partes acima identificadas resolvem aditar o Contrato de Administração de Imóveis nº #numero_contrato_administracao, firmado em #data_contrato_administracao, mediante as cláusulas e condições a seguir:</p><p style="text-align: justify;"><b>1 - Da inclusão de imóvel</b></p><p style="text-align: justify;">Em razão da inclusão de novo(s) imóvel(is) na administração, a Cláusula 1 do contrato passa a vigorar com a seguinte relação de imóveis administrados: #imoveis_administrados.</p><p style="text-align: justify;"><b>2 - Das condições aplicáveis</b></p><p style="text-align: justify;">Aplicam-se aos imóveis incluídos todas as condições do contrato, inclusive o mandato e os poderes nele conferidos à ADMINISTRADORA e a taxa de administração de #taxa_administracao (#taxa_administracao_extenso) sobre o valor do aluguel.</p><p style="text-align: justify;"><b>3 - Da ratificação</b></p><p style="text-align: justify;">Permanecem em vigor todas as demais cláusulas e condições do contrato original que não tenham sido alteradas por este termo aditivo.</p><div style="text-align: right;"><span style="font-size: 0.875rem;">Curionópolis, Pará, #data_hoje.</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_proprietario</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#cpf_cnpj_proprietario</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">PROPRIETÁRIO(A)</span></div><br><br><div style="text-align: center;"><span style="font-size: 0.875rem;">_______________________________________________</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">#nome_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">CNPJ #cnpj_administradora</span></div><div style="text-align: center;"><span style="font-size: 0.875rem;">ADMINISTRADORA</span></div>$modelo$
where nome = 'TERMO ADITIVO DE INCLUSÃO DE IMÓVEL - CONTRATO DE ADMINISTRAÇÃO';
